// ------------------------------------------------------------------
// APP
// ------------------------------------------------------------------
export default function Portfolio() {
  const [active, setActive] = useState("home");

  const handleNavigate = (id) => {
    setActive(id);
    document.getElementById(id)?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    const ids = NAV_ITEMS.map((n) => n.id);
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            setActive(entry.target.id);
          }
        });
      },
      { rootMargin: "-40% 0px -50% 0px", threshold: 0 }
    );

    ids.forEach((id) => {
      const el = document.getElementById(id);
      if (el) observer.observe(el);
    });

    return () => observer.disconnect();
  }, []);

  return (
    <div style={{ backgroundColor: tokens.bg, minHeight: "100vh" }}>
      <GlobalStyles />
      <Nav active={active} onNavigate={handleNavigate} />
      <Home />
      <About />
      <Skills />
      <Projects />
      <Contact />

      <footer
        className="px-5 md:px-8 py-8 text-center"
        style={{ borderTop: `1px solid ${tokens.borderSoft}` }}
      >
        <p style={{ fontFamily: fontMono, color: tokens.mutedDim, fontSize: 12 }}>
          © {new Date().getFullYear()} Shruti Jain — built with React
        </p>
      </footer>
    </div>
  );
}
